css:
:host {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #3498db;
  --warm: #e74c3c;
  --line: #bdc3c7;
  --paper: #f8f9fa;
  --font-base: 15px;
  --font-ui: 13px;
}

.chapter-section {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem 1.5rem;
  margin-bottom: 2rem;
  border-left: 4px solid var(--accent);
}

.section-header h2 {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.section-summary {
  font-size: var(--font-base);
  color: var(--muted);
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

.interaction-panel {
  background: #fff;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  margin-bottom: 1.5rem;
  display: flex;
  gap: 1.5rem;
  align-items: center;
  flex-wrap: wrap;
}

.control-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.control-group label {
  font-size: var(--font-ui);
  font-weight: 600;
}

.control-group select,
.control-group input[type="range"] {
  font-size: var(--font-ui);
  padding: 0.25rem;
  border: 1px solid var(--line);
  border-radius: 3px;
}

.reset-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 3px;
  cursor: pointer;
  font-size: var(--font-ui);
}

.reset-btn:hover {
  opacity: 0.9;
}

.data-visualization {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 768px) {
  .data-visualization {
    grid-template-columns: 1fr;
  }
}

.chart-container {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1rem;
  position: relative;
}

.chart-legend {
  display: flex;
  gap: 1rem;
  margin-top: 0.5rem;
  font-size: var(--font-ui);
  flex-wrap: wrap;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.legend-color {
  width: 12px;
  height: 12px;
  border-radius: 2px;
}

.data-table-container {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  overflow: auto;
  max-height: 300px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--font-ui);
}

th, td {
  padding: 0.5rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
}

th {
  background: #f1f2f6;
  font-weight: 600;
}

.evidence-notes {
  background: #f1f2f6;
  padding: 1rem;
  border-radius: 4px;
  font-size: var(--font-base);
  color: var(--muted);
}

.source-btn {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 0.25rem 0.5rem;
  border-radius: 3px;
  cursor: pointer;
  font-size: var(--font-ui);
  margin-left: 0.5rem;
}

.source-btn:hover {
  background: var(--accent);
  color: #fff;
}

.threshold-marker {
  margin-top: 1rem;
  padding: 0.5rem;
  background: #fff3cd;
  border-left: 3px solid var(--warm);
  font-size: var(--font-ui);
}

.comparison-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

.method-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1rem;
}

.method-card.highlight {
  border-color: var(--accent);
  background: #f0f8ff;
}

.method-card h3 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
}

.method-card ul {
  padding-left: 1.2rem;
  font-size: var(--font-base);
  color: var(--muted);
}
