(function() {
  const tables = window.paperMindData.tables;
  const sources = window.paperMindData.sources;

  // 近场仿真数据映射
  const nearArbitraryTable = tables.find(t => t.id === 'p8-Table_1');
  const nearLinearTable = tables.find(t => t.id === 'p9-TABLE_II');
  const farArbitraryTable = tables.find(t => t.id === 'p9-TABLE_III');
  const farLinearTable = tables.find(t => t.id === 'p9-TABLE_IV');

  // 颜色映射
  const colors = {
    A: '#95a5a6', // SI
    B: '#3498db', // Taylor
    C: '#2ecc71', // Proposed (simplified)
    D: '#27ae60', // Proposed (full)
    E: '#e74c3c'  // CRLB
  };

  const labels = {
    A: 'SI 法',
    B: '泰勒级数法',
    C: '本文方案 C',
    D: '本文方案 D',
    E: 'CRLB (理论)'
  };

  // 近场交互逻辑
  const scenarioSelect = document.getElementById('scenario-select');
  const sensorCountInput = document.getElementById('sensor-count');
  const sensorCountDisplay = document.getElementById('sensor-count-display');
  const mseChart = document.getElementById('mse-chart');
  const mseTableBody = document.querySelector('#mse-table tbody');
  const chartLegend = document.getElementById('chart-legend');
  const resetNearBtn = document.getElementById('reset-near');

  let currentScenario = 'near-arbitrary';
  let currentM = 5;

  function getTableForScenario(scenario) {
    if (scenario === 'near-arbitrary') return nearArbitraryTable;
    if (scenario === 'near-linear') return nearLinearTable;
    if (scenario === 'far-arbitrary') return farArbitraryTable;
    if (scenario === 'far-linear') return farLinearTable;
    return null;
  }

  function renderChart(scenario, m) {
    const table = getTableForScenario(scenario);
    if (!table) return;

    const ctx = mseChart.getContext('2d');
    ctx.clearRect(0, 0, mseChart.width, mseChart.height);

    const methods = ['A', 'B', 'C', 'D', 'E'];
    const mKey = `M = ${m}`;
    sensorCountInput.min = scenario.startsWith('far') ? '4' : '3';
    if(m < Number(sensorCountInput.min)){sensorCountInput.value=sensorCountInput.min;updateNearDisplay();return;}
    const data = [];

    methods.forEach(method => {
      const row = table.rows.find(r => r.label === method);
      if (row && row.values[mKey]) {
        const val = row.values[mKey];
        data.push({
          method,
          value: val === 'no sol.' ? null : parseFloat(val),
          label: labels[method]
        });
      }
    });

    // 绘制柱状图
    const barWidth = 40;
    const gap = 20;
    const startX = 50;
    const maxY = Math.max(...data.filter(d => d.value !== null).map(d => d.value), 1);
    const chartHeight = 250;
    const scaleY = chartHeight / maxY;

    data.forEach((d, i) => {
      if (d.value === null) {
        ctx.fillStyle = '#ccc';
        ctx.font = '12px sans-serif';
        ctx.fillText('无解', startX + i * (barWidth + gap), 150);
        return;
      }
      const barHeight = d.value * scaleY;
      ctx.fillStyle = colors[d.method];
      ctx.fillRect(startX + i * (barWidth + gap), chartHeight - barHeight, barWidth, barHeight);
      ctx.fillStyle = '#000';
      ctx.fillText(d.value.toPrecision(6), startX + i * (barWidth + gap), chartHeight - barHeight - 5);
    });

    // 更新图例
    chartLegend.innerHTML = '';
    methods.forEach(method => {
      const item = document.createElement('div');
      item.className = 'legend-item';
      item.innerHTML = `<span class="legend-color" style="background:${colors[method]}"></span>${labels[method]}`;
      chartLegend.appendChild(item);
    });

    // 更新表格
    mseTableBody.innerHTML = '';
    data.forEach(d => {
      const tr = document.createElement('tr');
      tr.innerHTML = `<td>${d.label}</td><td>${d.value === null ? '无解' : d.value.toPrecision(6)}</td><td>${d.value === null ? '失效' : '有效'}</td>`;
      mseTableBody.appendChild(tr);
    });
  }

  function updateNearDisplay() {
    currentScenario = scenarioSelect.value;
    currentM = parseInt(sensorCountInput.value);
    sensorCountDisplay.textContent = currentM;
    renderChart(currentScenario, currentM);
  }

  scenarioSelect.addEventListener('change', updateNearDisplay);
  sensorCountInput.addEventListener('input', updateNearDisplay);
  resetNearBtn.addEventListener('click', () => {
    scenarioSelect.value = 'near-arbitrary';
    sensorCountInput.value = 5;
    updateNearDisplay();
  });


  updateNearDisplay();
})();
